solutionCode:
pub fn cracha(nome: String) -> String {
    let letras = nome.len();
    let frente = nome.clone();
    let mut verso = nome;
    verso.push_str(" | acesso liberado");
    let rotulo = String::from("CRACHA");
    let cabecalho = rotulo + " do evento";
    format!("{cabecalho}: {frente} ({letras} letras) - verso: {verso}")
}

testsCode:
use desafio::cracha;

#[test]
fn testa_o_cracha_da_ana() {
    assert_eq!(cracha(String::from("Ana")), "CRACHA do evento: Ana (3 letras) - verso: Ana | acesso liberado");
}

#[test]
fn testa_o_cracha_do_luiz() {
    let apelido = "Luiz";
    assert_eq!(cracha(apelido.to_string()), "CRACHA do evento: Luiz (4 letras) - verso: Luiz | acesso liberado");
}

#[test]
fn testa_o_cracha_da_sol() {
    let apelido = "Sol";
    assert_eq!(cracha(apelido.to_string()), "CRACHA do evento: Sol (3 letras) - verso: Sol | acesso liberado");
}
